import{_ as u,C as c,o as t,c as h,j as a,a as i,G as r,b as s,w as n,a9 as l,a3 as d}from"./chunks/framework.exbasbhr.js";const y=JSON.parse('{"title":"Whiteboard Writing System","description":"Whiteboard Writing System","frontmatter":{"date":"2026-05-05T00:00:00.000Z","author":["Makitoid","Qoder"],"title":"Whiteboard Writing System","description":"Whiteboard Writing System"},"headers":[],"relativePath":"en/dev/whiteboard-system/index.md","filePath":"en/dev/whiteboard-system/index.md"}'),m={name:"en/dev/whiteboard-system/index.md"};function p(A,e,k,S,f,I){const g=c("ArticleMetadata"),o=c("Mermaid");return t(),h("div",null,[e[5]||(e[5]=a("h1",{id:"whiteboard-writing-system",tabindex:"-1"},[i("Whiteboard Writing System "),a("a",{class:"header-anchor",href:"#whiteboard-writing-system","aria-label":'Permalink to "Whiteboard Writing System"'},"​")],-1)),r(g),e[6]||(e[6]=a("h2",{id:"introduction",tabindex:"-1"},[i("Introduction "),a("a",{class:"header-anchor",href:"#introduction","aria-label":'Permalink to "Introduction"'},"​")],-1)),e[7]||(e[7]=a("p",null,"This document addresses the whiteboard writing system of InkCanvasForClass, providing systematic technical explanations surrounding the use of the InkCanvas control, ink data acquisition and storage, smoothing algorithms, hardware-accelerated processors, ink fadeout effects, rendering and visual feedback, color and brush size/opacity control, and more. The document aims to help developers quickly understand and extend the writing experience and performance metrics of the system.",-1)),e[8]||(e[8]=a("h2",{id:"project-structure",tabindex:"-1"},[i("Project Structure "),a("a",{class:"header-anchor",href:"#project-structure","aria-label":'Permalink to "Project Structure"'},"​")],-1)),e[9]||(e[9]=a("ul",null,[a("li",null,"Core Writing and Rendering: MainWindow.xaml.cs and its submodules are responsible for InkCanvas event bindings, real-time previews, multi-touch, color, and brush property settings, etc."),a("li",null,"Smoothing and Acceleration: InkSmoothingManager, AdvancedBezierSmoothing, ImprovedBezierSmoothing, HardwareAcceleratedInkProcessor, and InkSmoothingConfig in the Helpers directory provide capabilities such as asynchronous smoothing, Bezier curve fitting, GPU acceleration, and configuration management."),a("li",null,"Fadeout and Freeze: InkFadeManager implements ink fadeout animations and visual management; MW_InkFreeze provides page freezing/unfreezing and non-editable protection."),a("li",null,"Tools and Interactions: MW_Eraser, MW_ShapeDrawing, MW_TouchEvents, and MW_BoardControls modules are responsible for eraser, shape drawing, touch events, and whiteboard page management, respectively.")],-1)),(t(),s(l,null,{default:n(()=>[r(o,{id:"mermaid-34",class:"mermaid",graph:"graph%20TB%0Asubgraph%20%22MainWindow%20and%20Canvas%22%0AMW%5B%22MainWindow.xaml.cs%3Cbr%2F%3EEvent%20Binding%2FColor%2FTouch%22%5D%0AIC%5B%22InkCanvas%20Control%22%5D%0Aend%0Asubgraph%20%22Smoothing%20and%20Acceleration%22%0AISM%5B%22InkSmoothingManager.cs%22%5D%0AABS%5B%22AdvancedBezierSmoothing.cs%22%5D%0AIBS%5B%22ImprovedBezierSmoothing.cs%22%5D%0AHAI%5B%22HardwareAcceleratedInkProcessor.cs%22%5D%0AISC%5B%22InkSmoothingConfig.cs%22%5D%0Aend%0Asubgraph%20%22Rendering%20and%20Effects%22%0AIFM%5B%22InkFadeManager.cs%22%5D%0AMWF%5B%22MW_InkFreeze.cs%22%5D%0AME%5B%22MW_Eraser.cs%22%5D%0AMS%5B%22MW_ShapeDrawing.cs%22%5D%0AMTC%5B%22MW_TouchEvents.cs%22%5D%0AMBC%5B%22MW_BoardControls.cs%22%5D%0Aend%0AMW%20--%3E%20IC%0AIC%20--%3E%20ISM%0AISM%20--%3E%20ABS%0AISM%20--%3E%20IBS%0AISM%20--%3E%20HAI%0AISM%20--%3E%20ISC%0AIC%20--%3E%20IFM%0AIC%20--%3E%20ME%0AIC%20--%3E%20MS%0AIC%20--%3E%20MTC%0AIC%20--%3E%20MBC%0AMBC%20--%3E%20MWF%0A"})]),fallback:n(()=>e[0]||(e[0]=[i(" Loading... ")])),_:1})),e[10]||(e[10]=d('<h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li>InkCanvas Control: Carries ink input, real-time preview, stroke rendering, and UI event interactions.</li><li>InkSmoothingManager: Uniformly schedules asynchronous smoothing, hardware acceleration, and traditional processing paths, supporting hot configuration updates and performance monitoring.</li><li>AdvancedBezierSmoothing / ImprovedBezierSmoothing: Provide Bezier curve fitting, adaptive interpolation, resampling, and pressure value interpolation.</li><li>HardwareAcceleratedInkProcessor: GPU-based path geometry smoothing and parallel Bezier calculations.</li><li>InkFadeManager: Manages ink fadeout animations, segmented rendering, and visual containers, supporting highlighter special effects.</li><li>MW_InkFreeze: Page-level freezing/unfreezing, protecting written contents from editing.</li><li>MW_Eraser / MW_ShapeDrawing / MW_TouchEvents: Eraser geometric hit testing, shape drawing, and touch real-time stylus tip states.</li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>The system adopts a layered design of &quot;event-driven + smoothing pipeline + rendering and effects&quot;:</p><ul><li>Event Layer: MainWindow binds StylusDown/Move/Up events of InkCanvas and touch events, switching editing modes and real-time stylus tip states on demand.</li><li>Smoothing Layer: InkSmoothingManager selects AsyncAdvancedBezierSmoothing, HardwareAcceleratedInkProcessor, or traditional paths based on configurations, supporting concurrent tasks and cancellations.</li><li>Rendering Layer: InkCanvas renders ink internally; InkFadeManager attaches visual layers to ink, realizing fadeout and segmented animations.</li><li>Tools Layer: MW_Eraser provides geometric/stroke erasures; MW_ShapeDrawing provides shape drawing previews; MW_InkFreeze provides page freeze protection.</li></ul>',5)),(t(),s(l,null,{default:n(()=>[r(o,{id:"mermaid-103",class:"mermaid",graph:"sequenceDiagram%0Aparticipant%20User%20as%20%22User%22%0Aparticipant%20MW%20as%20%22MainWindow%22%0Aparticipant%20IC%20as%20%22InkCanvas%22%0Aparticipant%20ISM%20as%20%22InkSmoothingManager%22%0Aparticipant%20ABS%20as%20%22AdvancedBezierSmoothing%22%0Aparticipant%20HAI%20as%20%22HardwareAcceleratedInkProcessor%22%0AUser-%3E%3EMW%20%3A%20%22Handwriting%2Ftouch%20input%22%0AMW-%3E%3EIC%20%3A%20%22Bind%20events%20%2F%20set%20edit%20mode%22%0AIC-%3E%3EISM%20%3A%20%22Submit%20raw%20stroke%22%0Aalt%20%22Asynchronous%20Smoothing%22%0AISM-%3E%3EABS%20%3A%20%22SmoothStrokeAsync(...)%22%0AABS--%3E%3EISM%20%3A%20%22Smoothed%20stroke%22%0Aelse%20%22Hardware%20Acceleration%22%0AISM-%3E%3EHAI%20%3A%20%22SmoothStrokeWithGPU(...)%22%0AHAI--%3E%3EISM%20%3A%20%22GPU-smoothed%20stroke%22%0Aelse%20%22Traditional%20Synchronous%22%0AISM-%3E%3EISM%20%3A%20%22Task.Run(...)%20Traditional%20smoothing%22%0Aend%0AISM--%3E%3EIC%20%3A%20%22Return%20smoothed%20stroke%22%0AIC--%3E%3EUser%20%3A%20%22Render%20ink%20%2F%20fadeout%20effects%22%0A"})]),fallback:n(()=>e[1]||(e[1]=[i(" Loading... ")])),_:1})),e[11]||(e[11]=d('<h2 id="detailed-component-analysis" tabindex="-1">Detailed Component Analysis <a class="header-anchor" href="#detailed-component-analysis" aria-label="Permalink to &quot;Detailed Component Analysis&quot;">​</a></h2><h3 id="inkcanvas-control-and-event-bindings" tabindex="-1">InkCanvas Control and Event Bindings <a class="header-anchor" href="#inkcanvas-control-and-event-bindings" aria-label="Permalink to &quot;InkCanvas Control and Event Bindings&quot;">​</a></h3><ul><li>MainWindow binds the StylusDown/Move/Up events of InkCanvas to processing functions, switching editing modes (e.g., None/Ink/EraseByPoint/EraseByStroke/Select) on demand, and handles touch inputs and multi-touch states.</li><li>Controls stroke appearance and behavior via EditingMode and DefaultDrawingAttributes; real-time preview reduces flickering through temporary strokes and throttled updates.</li></ul><h3 id="ink-data-acquisition-and-storage" tabindex="-1">Ink Data Acquisition and Storage <a class="header-anchor" href="#ink-data-acquisition-and-storage" aria-label="Permalink to &quot;Ink Data Acquisition and Storage&quot;">​</a></h3><ul><li>Ink is represented by Stroke and StylusPointCollection containing position and pressure information; the InkCanvas.Strokes collection saves all ink.</li><li>Page-level Management: MW_BoardControls maintains the StrokeCollection and history TimeMachineHistories for each page, supporting switching/adding/deleting pages and persistences.</li><li>Freezing Protection: MW_InkFreeze adds property flags to ink on frozen pages, preventing modifications by misoperations.</li></ul><h3 id="inksmoothingmanager-and-smoothing-algorithms" tabindex="-1">InkSmoothingManager and Smoothing Algorithms <a class="header-anchor" href="#inksmoothingmanager-and-smoothing-algorithms" aria-label="Permalink to &quot;InkSmoothingManager and Smoothing Algorithms&quot;">​</a></h3><ul><li>Unified entry SmoothStrokeAsync/SmoothStroke selects AsyncAdvancedBezierSmoothing, HardwareAcceleratedInkProcessor, or traditional paths based on configurations.</li><li>AsyncAdvancedBezierSmoothing uses quintic Bezier sliding window fitting, adaptive interpolation steps, exponential smoothing, and equidistant resampling, balancing quality and performance.</li><li>HardwareAcceleratedInkProcessor uses PathGeometry and parallel Bezier calculations, keeping pressure information, suitable for GPU acceleration scenarios.</li><li>InkSmoothingConfig provides quality levels (Performance/Balanced/Quality) and parameter mappings, supporting loading from settings and validations.</li></ul>',7)),(t(),s(l,null,{default:n(()=>[r(o,{id:"mermaid-167",class:"mermaid",graph:"classDiagram%0Aclass%20InkSmoothingManager%20%7B%0A%2BSmoothStrokeAsync(...)%0A%2BSmoothStroke(...)%0A%2BUpdateConfig()%0A%2BGetPerformanceStats()%0A%2BCancelAllTasks()%0A%2BIsHardwareAccelerationSupported()%0A%2BGetRecommendedConfig()%0A%2BApplyRecommendedSettings()%0A%7D%0Aclass%20AsyncAdvancedBezierSmoothing%20%7B%0A%2BSmoothingStrength%0A%2BResampleInterval%0A%2BInterpolationSteps%0A%2BUseHardwareAcceleration%0A%2BMaxConcurrentTasks%0A%2BUseAdaptiveInterpolation%0A%2BCurveTension%0A%2BSmoothStrokeAsync(...)%0A%2BCancelAllTasks()%0A%7D%0Aclass%20HardwareAcceleratedInkProcessor%20%7B%0A%2BSmoothStrokeWithGPU(...)%0A%2BParallelBezierInterpolation(...)%0A%7D%0Aclass%20InkSmoothingConfig%20%7B%0A%2BQuality%0A%2BSmoothingStrength%0A%2BResampleInterval%0A%2BInterpolationSteps%0A%2BUseHardwareAcceleration%0A%2BUseAsyncProcessing%0A%2BMaxConcurrentTasks%0A%2BApplyQualitySettings()%0A%2BFromSettings()%0A%2BValidate()%0A%7D%0AInkSmoothingManager%20--%3E%20AsyncAdvancedBezierSmoothing%20%3A%20%22Delegate%22%0AInkSmoothingManager%20--%3E%20HardwareAcceleratedInkProcessor%20%3A%20%22Delegate%22%0AInkSmoothingManager%20--%3E%20InkSmoothingConfig%20%3A%20%22Read%20Configuration%22%0A"})]),fallback:n(()=>e[2]||(e[2]=[i(" Loading... ")])),_:1})),e[12]||(e[12]=d('<h3 id="hardware-accelerated-ink-processor" tabindex="-1">Hardware-Accelerated Ink Processor <a class="header-anchor" href="#hardware-accelerated-ink-processor" aria-label="Permalink to &quot;Hardware-Accelerated Ink Processor&quot;">​</a></h3><ul><li>Uses RenderTargetBitmap and DrawingVisual, cooperating with RenderOptions settings to enhance GPU rendering quality.</li><li>Generates smooth curves via PathGeometry, and converts back to StylusPoint collections, keeping pressure information.</li><li>Parallel Bezier interpolation uses Parallel.For, significantly enhancing calculation efficiency of multi-segment curves.</li></ul><h3 id="ink-fadeout-effects" tabindex="-1">Ink Fadeout Effects <a class="header-anchor" href="#ink-fadeout-effects" aria-label="Permalink to &quot;Ink Fadeout Effects&quot;">​</a></h3><ul><li>InkFadeManager creates Path visual elements for each stroke, supporting unified/progressive animation strategies.</li><li>Highlighters adopt special blending and slight scaling to enhance the &quot;evaporation&quot; visual; normal ink is rendered by segments, guaranteeing that short strokes are also fully displayed.</li><li>Supports dynamically calculating animation durations based on stroke length and global speed multipliers, providing unified fadeout lifecycle management.</li></ul>',4)),(t(),s(l,null,{default:n(()=>[r(o,{id:"mermaid-208",class:"mermaid",graph:"flowchart%20TD%0AStart(%5B%22Add%20stroke%20to%20fadeout%20queue%22%5D)%20--%3E%20CreateVisual%5B%22Create%20stroke%20visual%20element%3Cbr%2F%3EPath%20%2B%20Geometry%22%5D%0ACreateVisual%20--%3E%20DecideStrategy%7B%22Highlighter%3F%22%7D%0ADecideStrategy%20--%3E%20%7CYes%7C%20Unified%5B%22Unified%20fadeout%20animation%3Cbr%2F%3EOpacity%20%2B%20slight%20scaling%22%5D%0ADecideStrategy%20--%3E%20%7CNo%7C%20Segmented%5B%22Segmented%20fadeout%20animation%3Cbr%2F%3EMulti-segment%20path%20%2B%20delay%20sequence%22%5D%0AUnified%20--%3E%20Animate%5B%22BeginAnimation(Opacity)%22%5D%0ASegmented%20--%3E%20Segment%5B%22Calculate%20segment%20count%20by%20length%2Fdensity%22%5D%0ASegment%20--%3E%20StartSeg%5B%22Start%20fadeout%20timers%20segment%20by%20segment%22%5D%0AStartSeg%20--%3E%20Cleanup%5B%22Clean%20up%20container%20after%20all%20completed%22%5D%0AAnimate%20--%3E%20End(%5B%22Complete%22%5D)%0ACleanup%20--%3E%20End%0A"})]),fallback:n(()=>e[3]||(e[3]=[i(" Loading... ")])),_:1})),e[13]||(e[13]=d('<h3 id="rendering-and-visual-feedback" tabindex="-1">Rendering and Visual Feedback <a class="header-anchor" href="#rendering-and-visual-feedback" aria-label="Permalink to &quot;Rendering and Visual Feedback&quot;">​</a></h3><ul><li>Real-time Preview: MW_ShapeDrawing uses throttled updates (around 60fps) to reduce UI jitters; adds new strokes before removing old strokes to avoid flickering.</li><li>Pressure Visual: MultiTouchInput maps pressure values to stroke thicknesses, enhancing writing realism.</li><li>Stroke Effects: InkFadeManager sets rounded/flat end caps and slight blur for highlighters, enhancing visual hierarchies.</li></ul><h3 id="color-management-brush-size-and-opacity" tabindex="-1">Color Management, Brush Size and Opacity <a class="header-anchor" href="#color-management-brush-size-and-opacity" aria-label="Permalink to &quot;Color Management, Brush Size and Opacity&quot;">​</a></h3><ul><li>Color: MW_Colors sets InkCanvas.DefaultDrawingAttributes.Color according to themes and pen types, maintaining the most recently used color index.</li><li>Brush Size: Sets Width/Height and StylusTip; laser pen mode is configured independently.</li><li>Opacity: Links the Alpha channel of DrawingAttributes.Color with sliders, supporting semi-translucent stroke effects.</li></ul><h3 id="eraser-and-shape-drawing" tabindex="-1">Eraser and Shape Drawing <a class="header-anchor" href="#eraser-and-shape-drawing" aria-label="Permalink to &quot;Eraser and Shape Drawing&quot;">​</a></h3><ul><li>Geometric Erasure: MW_Eraser uses InkCanvas.Strokes.GetIncrementalStrokeHitTester and StylusShape (ellipse/rectangle) to perform hit testing, supporting real-time feedback and replacement/deletion.</li><li>Stroke Erasure: Directly removes after filtering out frozen ink.</li><li>Shape Drawing: MW_ShapeDrawing generates geometry point sets on temporary strokes, adding them to InkCanvas.Strokes after submission.</li></ul><h2 id="dependency-analysis" tabindex="-1">Dependency Analysis <a class="header-anchor" href="#dependency-analysis" aria-label="Permalink to &quot;Dependency Analysis&quot;">​</a></h2><ul><li>InkSmoothingManager depends on AsyncAdvancedBezierSmoothing, HardwareAcceleratedInkProcessor, and InkSmoothingConfig, forming pluggable smoothing strategies.</li><li>InkFadeManager depends on InkCanvas.Children and Dispatcher, managing the visual layer independently to avoid coupling with core ink data.</li><li>MW_BoardControls collaborates with TimeMachineHistories, realizing page-level ink persistence and recovery.</li><li>MW_Eraser is tightly coupled with InkCanvas.Strokes/EraserShape, ensuring erasure hits and performances.</li></ul>',8)),(t(),s(l,null,{default:n(()=>[r(o,{id:"mermaid-294",class:"mermaid",graph:"graph%20LR%0AISM%5B%22InkSmoothingManager%22%5D%20--%3E%20ABS%5B%22AsyncAdvancedBezierSmoothing%22%5D%0AISM%20--%3E%20HAI%5B%22HardwareAcceleratedInkProcessor%22%5D%0AISM%20--%3E%20ISC%5B%22InkSmoothingConfig%22%5D%0AIFM%5B%22InkFadeManager%22%5D%20--%3E%20IC%5B%22InkCanvas%22%5D%0AMWF%5B%22MW_InkFreeze%22%5D%20--%3E%20IC%0AMBC%5B%22MW_BoardControls%22%5D%20--%3E%20IC%0AME%5B%22MW_Eraser%22%5D%20--%3E%20IC%0AMS%5B%22MW_ShapeDrawing%22%5D%20--%3E%20IC%0A"})]),fallback:n(()=>e[4]||(e[4]=[i(" Loading... ")])),_:1})),e[14]||(e[14]=d('<h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><ul><li>Concurrency and Rate Limiting: AsyncAdvancedBezierSmoothing uses semaphores to limit concurrent task counts, avoiding CPU/GPU overload.</li><li>Adaptive Interpolation: Dynamically adjusts interpolation steps based on curve length and curvature, balancing quality and speed.</li><li>Equidistant Resampling: Resamples when point counts are excessive, controlling the upper limit of output points, reducing rendering burdens.</li><li>GPU Acceleration: HardwareAcceleratedInkProcessor uses PathGeometry and parallel calculations, suitable for smoothing large batches of strokes.</li><li>Fadeout Optimization: InkFadeManager uses segmented rendering and delay sequences, avoiding creation of massive UI elements at once that leads to stutters.</li></ul><h2 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h2><ul><li>Smoothing Failure Fallback: InkSmoothingManager catches exceptions and falls back to original strokes, avoiding interruptions to the writing flow.</li><li>Timeout Protection: Synchronous smoothing provides timeout protections, logging and returning original strokes after timeouts.</li><li>Fadeout Anomalies: InkFadeManager catches exceptions at various stages and cleans up resources, guaranteeing consistent UI states.</li><li>Erasure Failure: MW_Eraser filters out frozen ink during geometric erasures to avoid accidental deletions; submits history records at the end.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>This system realizes high-quality, low-latency whiteboard writing experiences through the combination of &quot;event-driven + pluggable smoothing strategies + GPU acceleration + fadeout visuals&quot;. InkSmoothingManager provides flexible configurations and performance monitoring; HardwareAcceleratedInkProcessor and AdvancedBezierSmoothing achieve a good balance between quality and performance; InkFadeManager and modules like MW_Eraser/MW_ShapeDrawing build a complete writing ecosystem together. Developers can extend custom stroke effects and rendering strategies based on existing interfaces.</p><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><ul><li>Recommended Practices <ul><li>Use InkSmoothingManager.GetRecommendedConfig() to automatically adapt to device performances.</li><li>For highlighters, it is recommended to enable the highlighter special effects of InkFadeManager.</li><li>Prioritize enabling hardware acceleration and asynchronous smoothing in large ink scenarios.</li><li>Adjust SmoothingStrength/ResampleInterval/InterpolationSteps through InkSmoothingConfig to match target quality levels.</li></ul></li><li>Extension Directions <ul><li>Custom Stroke Effects: Extend Path effects and animation curves in InkFadeManager.</li><li>Custom Smoothing Algorithms: Implement interfaces similar to AdvancedBezierSmoothing, integrating into InkSmoothingManager.</li><li>Multi-device Collaboration: Combine TimeMachineHistories and MW_BoardControls to realize stroke synchronizations across pages/devices.</li></ul></li></ul>',8))])}const b=u(m,[["render",p]]);export{y as __pageData,b as default};
